    mountPoint(name){const c=this.cameraPosition(name);return this.mountView==='top'?{x:240+(c.y-this.vehicleBox.location.y)*this.mountScale,y:200-(c.x-this.vehicleBox.location.x)*this.mountScale}:{x:240+(c.x-this.vehicleBox.location.x)*this.mountScale,y:270-c.z*this.mountScale}},
    fovPath(name){const c=this.cameraPosition(name),p={x:240+(c.y-this.vehicleBox.location.y)*this.mountScale,y:200-(c.x-this.vehicleBox.location.x)*this.mountScale};const point=a=>({x:p.x+Math.sin(a*Math.PI/180)*155,y:p.y-Math.cos(a*Math.PI/180)*155});const a=point(c.yaw-c.fov/2),b=point(c.yaw+c.fov/2);return 'M'+p.x+','+p.y+' L'+a.x+','+a.y+' A155,155 0 0 1 '+b.x+','+b.y+' Z'},
