    beginMirror(e,name,mode){this.cameraName=name;const c=this.cameras[name],r=this.$refs.layoutCanvas.getBoundingClientRect();this.drag={name,mode,x:e.clientX,y:e.clientY,sx:c.screen_x,sy:c.screen_y,w:c.width,h:c.height,rw:r.width,rh:r.height}},
