    get filteredSessions(){return this.sessions.filter(s=>(this.statusFilter==='all'||s.status===this.statusFilter)&&(!this.search||(s.subject+' '+s.id).toLowerCase().includes(this.search.toLowerCase()))&&(!this.dateFrom||s.day>=this.dateFrom)&&(!this.dateTo||s.day<=this.dateTo))},
    recentMonth(){const now=new Date(),from=new Date(now);from.setDate(from.getDate()-30);const day=d=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');this.dateFrom=day(from);this.dateTo=day(now)},
    get selectedSessions(){return this.sessions.filter(s=>this.selectedIds.includes(s.id))},
